"""Write STATUS.md: a live production board, generated by a plain script (no AI usage).

Usage: python3 pipeline/status.py            # write STATUS.md once
       python3 pipeline/status.py --watch    # rewrite every 60 s, commit + push when it changes

Reads the episode files, the narration cache in $WORK_DIR, the finished videos, and the
running build processes.
"""

import json
import os
import re
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
WORK = Path(os.environ.get("WORK_DIR", ROOT / ".work"))
SEASON = 20
NARRATIVES = ["Case Files", "Why Is It Built Like That?", "Engineering Nonsense"]


def bar(done, total, width=20):
    fill = round(width * done / total) if total else 0
    return "█" * fill + "░" * (width - fill)


def building():
    out = subprocess.run(["pgrep", "-af", "pipeline/build.mjs"], capture_output=True, text=True).stdout
    return set(re.findall(r"build\.mjs (\d{3}-[\w-]+)", out))


def snapshot():
    active = building()
    rows, done = [], 0
    for f in sorted((ROOT / "episodes").glob("*.js")):
        name = f.stem
        src = f.read_text()
        case = (re.search(r"case: '([^']+)'", src) or [None, name])[1].title()
        style = "3D" if "style: '3d'" in src else "2D"
        video = ROOT / "videos" / f"{name}.mp4"
        clips = total = 0
        nj = WORK / name / "narration.json"
        if nj.exists():
            files = json.loads(nj.read_text()).get("files", [])
            total = len(files)
            clips = sum((WORK / name / "audio" / x).exists() for x in files)
        if name in active:
            state = f"🎬 rendering" if total and clips == total else f"🎙️ narrating {clips}/{total or '?'}"
        elif video.exists():
            state, done = "✅ done", done + 1
        elif total and clips == total:
            state = "⏳ narration ready, waiting to render"
        elif clips:
            state = f"⏸️ narration paused at {clips}/{total}"
        else:
            state = "📝 scripted, in queue"
        rows.append((name[:3], case, style, state))
    return rows, done


def render(rows, done):
    n = len(rows)
    season = (max(n, 1) - 1) // SEASON
    in_season = [r for r in rows if (int(r[0]) - 1) // SEASON == season]
    s_done = sum("done" in r[3] for r in in_season)
    name = NARRATIVES[season] if season < len(NARRATIVES) else "to be chosen"
    lines = [
        "# Production status",
        "",
        f"**Now:** {next((f'episode {r[0]} — {r[3]}' for r in rows if 'narrating' in r[3] or 'rendering' in r[3]), 'idle — nothing is building')}",
        "",
        f"**Finished videos:** {done} of {n} written &nbsp; `{bar(done, n)}`",
        "",
        f"**Narrative {season + 1}: {name}** — {s_done} of {SEASON} finished &nbsp; `{bar(s_done, SEASON)}`",
        "",
        "| # | Episode | Style | Status |",
        "|---|---|---|---|",
    ]
    lines += [f"| {a} | {b} | {c} | {d} |" for a, b, c, d in rows]
    return "\n".join(lines)


def write():
    body = render(*snapshot())
    path = ROOT / "STATUS.md"
    old = path.read_text() if path.exists() else ""
    if old.split("\n\n_Updated")[0] == body:
        return False
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    path.write_text(f"{body}\n\n_Updated {stamp} by `pipeline/status.py`. This file is rewritten automatically while a build is running._\n")
    return True


def git(*a):
    return subprocess.run(["git", "-C", str(ROOT), *a], capture_output=True, text=True)


def as_json():
    """Same snapshot as a JSON document, for the in-app tracker page."""
    rows, done = snapshot()
    season = (max(len(rows), 1) - 1) // SEASON
    return {
        "updatedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "now": next((f"Episode {r[0]} · {re.sub(r'^[^a-z]+', '', r[3])}" for r in rows if "narrating" in r[3] or "rendering" in r[3]), "Idle"),
        "done": done, "written": len(rows),
        "narrative": {"n": season + 1, "name": NARRATIVES[season] if season < len(NARRATIVES) else "To be chosen",
                      "done": sum("done" in r[3] for r in rows if (int(r[0]) - 1) // SEASON == season), "total": SEASON},
        "episodes": [{"n": a, "title": b, "style": c, "state": re.sub(r"^[^a-z]+", "", d),
                      "kind": "done" if "done" in d else "active" if ("narrating" in d or "rendering" in d) else "queued"} for a, b, c, d in rows],
    }


def dashboard():
    """Everything the Control Room dashboard shows, as channel/dashboard.json."""
    rows, done = snapshot()
    posted = json.loads((ROOT / "channel" / "posted.json").read_text()).get("youtube", {}) if (ROOT / "channel" / "posted.json").exists() else {}
    series = (ROOT / "channel" / "SERIES.md").read_text()
    plan = re.findall(r"^\| (\d{3})–(\d{3}) \| (?:\*\*)?(.+?)(?:\*\*)? \| (.+?) \|$", series, re.M)
    eps = []
    for f, (n, title, style, state) in zip(sorted((ROOT / "episodes").glob("*.js")), rows):
        src = f.read_text()
        md = ROOT / "videos" / f"{f.stem}.md"
        dur = re.search(r"· ([\d.]+) s", md.read_text()) if md.exists() else None
        yt = posted.get(f.stem, {})
        eps.append({
            "n": n, "title": title, "slug": f.stem, "style": style,
            "voice": (re.search(r"voice: '(v\d)'", src) or [None, "v1"])[1],
            "quiz": "quiz:" in src, "seconds": float(dur.group(1)) if dur else None,
            "build": "done" if "done" in state else "building" if ("narrating" in state or "rendering" in state) else "queued",
            "buildDetail": re.sub(r"^[^a-z]+", "", state),
            "youtube": yt.get("privacy") or ("outside" if yt.get("note") else "not posted"),
            "youtubeUrl": f"https://youtube.com/shorts/{yt['id']}" if yt.get("id") else "",
            "postedAt": yt.get("at", ""),
            "narrative": next((name for a, b, name, _ in plan if a <= n <= b), ""),
        })
    narr = []
    cur = None
    for a, b, name, what in plan:
        mine = [e for e in eps if a <= e["n"] <= b]
        built = sum(e["build"] == "done" for e in mine)
        status = "complete" if built >= 20 else "current" if mine and cur is None else "upcoming"
        if status == "current":
            cur = name
        narr.append({"range": f"{a}–{b}", "name": name, "what": re.sub(r"\s+\.", ".", re.sub(r"\*\*|\(for example.*?\)", "", what)).strip(),
                     "status": status, "written": len(mine), "built": built,
                     "posted": sum(e["youtube"] in ("public", "private", "outside") for e in mine), "total": 20})
    active = next((e for e in eps if e["build"] == "building"), None)
    pub = [e for e in eps if e["youtube"] in ("public", "private", "outside")]
    nxt = next((e for e in eps if e["youtube"] == "not posted" and e["build"] == "done"), None)
    status = [{
        "updatedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "activity": f"Building episode {active['n']}: {active['buildDetail']}" if active else "Idle: no episode is building",
        "activityKind": "building" if active else "idle",
        "narrative": cur or "",
        "built": done, "written": len(eps),
        "posted": len(pub), "public": sum(e["youtube"] == "public" for e in eps),
        "lastPostAt": max((e["postedAt"] for e in eps if e["postedAt"]), default=""),
        "nextToPost": f"{nxt['n']} {nxt['title']}" if nxt else "",
    }]
    return {"status": status, "narratives": narr, "episodes": eps}


def write_dashboard():
    path = ROOT / "channel" / "dashboard.json"
    data = dashboard()
    old = json.loads(path.read_text()) if path.exists() else None
    if old:
        old["status"][0]["updatedAt"] = data["status"][0]["updatedAt"]
    if old == data:
        return False
    path.write_text(json.dumps(data, indent=1) + "\n")
    return True


if __name__ == "__main__":
    if "--dashboard" in sys.argv:
        write_dashboard()
        sys.exit()
    if "--json" in sys.argv:
        print(json.dumps(as_json()))
        sys.exit()
    if "--watch" not in sys.argv:
        write()
        sys.exit()
    while True:
        try:
            changed = write() | write_dashboard()
            if changed:
                git("add", "STATUS.md", "channel/dashboard.json")
                git("commit", "-q", "--only", "STATUS.md", "channel/dashboard.json", "-m", "Update production status")
                git("push", "-q", "origin", "HEAD")
        except Exception as e:  # keep the board alive whatever happens
            print("status:", e, flush=True)
        time.sleep(60)
